    { \True  ${EFGI}$ là hình thang cân }
}{
\begin{tikzpicture}
            \coordinate (O) at (0, 1);
            \coordinate (D) at (-3, 0);
            \coordinate (C) at (2, 0);
            \coordinate (B) at (3, 2);
            \coordinate (A) at (-2, 2);
            \coordinate (H) at (-1.33, 0);
            \coordinate (K) at (1.33, 2);
            % Vẽ tứ giác
            \draw[thick] (D) -- (B);
            \draw[thick] (A) -- (B) -- (C) -- (D) -- (A);
            \draw[thick] (C) -- (K);
            \draw[thick] (A) -- (H);
            \draw[thick] (K) -- (H);
            % Ghi nhãn các điểm
            \node[below left] at (H) {$I$};
            \node[above right] at (B) {$F$};
            \node[below right] at (C) {$G$};
            \node[below left] at (D) {$H$};
            \node[above left] at (A){$E$};
            \node[above right] at (K) {$J$};
            \node[below] at (O) {$O$};
    \end{tikzpicture}
}
\loigiai{
Ta có $EI \bot FH$, $GJ \bot FH$ suy ra $EI // GJ$\\
Lại có $EJ//IG $ nên ${EIGJ}$ là hình bình hành.\\
